import{_ as t,c as a,o as r,ag as n}from"./chunks/framework.ARG558ZT.js";const u=JSON.parse('{"title":"AWS homework: required course tracks and optional extensions","description":"","frontmatter":{},"headers":[],"relativePath":"practice/aws/index.md","filePath":"practice/aws/index.md"}'),o={name:"practice/aws/index.md"};function s(i,e,d,c,l,p){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="aws-homework-required-course-tracks-and-optional-extensions" tabindex="-1">AWS homework: required course tracks and optional extensions <a class="header-anchor" href="#aws-homework-required-course-tracks-and-optional-extensions" aria-label="Permalink to “AWS homework: required course tracks and optional extensions”">​</a></h1><p>The two course tracks now form the required AWS practice path. <strong>Every supplied task is mandatory here</strong>, including original optional tasks, bonus challenges and guide extensions. This is a local learning-path decision; it does not change EPAM&#39;s original grading criteria.</p><p>All learner work remains <strong>not started</strong> until independently completed and evidenced. Writing these specifications does not create AWS resources or complete any lab.</p><h2 id="reading-and-implementation-order" tabindex="-1">Reading and implementation order <a class="header-anchor" href="#reading-and-implementation-order" aria-label="Permalink to “Reading and implementation order”">​</a></h2><p>Start with the <a href="./../../aws/beginner-guide.html">AWS beginner guide</a> and <a href="./../../aws/account-and-tools.html">account/tool setup</a>. Follow Practitioner P01–P08 in order to build the integrated store. Follow Associate A01–A12 in order for infrastructure and delivery depth; A12 denotes the AI lab, which the source also calls “Lab 11.” Keep the two Lab 11s distinct.</p><table tabindex="0"><thead><tr><th>Track</th><th>Required work</th><th>Main contribution</th></tr></thead><tbody><tr><td><a href="./practitioner.html">Practitioner</a></td><td>P01–P08, including promoted extensions</td><td>One integrated CDK application</td></tr><tr><td><a href="./associate.html">Associate</a></td><td>A01–A12, including promoted extensions and guide bonuses</td><td>Infrastructure, networking, alternate interfaces and delivery</td></tr><tr><td><a href="./optional-extensions.html">Optional additions</a></td><td>X01–X12, newly proposed here</td><td>Failure recovery, security, performance and operational gaps</td></tr></tbody></table><h2 id="what-repeating-means" tabindex="-1">What “repeating” means <a class="header-anchor" href="#what-repeating-means" aria-label="Permalink to “What “repeating” means”">​</a></h2><p><strong>Repeating</strong> marks material already practiced in another module or track. It does not mean “skip.” Reuse a verified resource when compatible, then demonstrate the new interface, configuration or behavior. For example, provisioning a bucket manually and later with CloudFormation repeats the service but adds reproducibility. Do not create a second account simply to satisfy the second account-setup task; recheck the existing account and record current evidence.</p><p>The <a href="./repeat-map.html">repeat map</a> records these overlaps. Within a task, alternative platforms or apps remain alternatives: choose one supported OS, IDE, frontend and database option unless an explicit comparison is requested. “Investigate packages” does not require building an application with every package. Generic “next steps” suggestions are not additional deliverables beyond the enumerated tasks.</p><h2 id="preserve-the-course-contracts" tabindex="-1">Preserve the course contracts <a class="header-anchor" href="#preserve-the-course-contracts" aria-label="Permalink to “Preserve the course contracts”">​</a></h2><p>Practitioner uses the course template and exact file paths, exported classes, prop interfaces, environment variable names, resource settings and API shapes. The module pages retain these details. Do not modernize away a tested contract simply because the conceptual notes show a different example.</p><p>Use the template&#39;s actual validation scripts. The supplied Practitioner specifications use Node.js 22, TypeScript, <code>npm run sync-tests -- module-N</code>, <code>npm run deploy</code>, <code>npm run test:unit</code>, <code>npm run test:e2e</code> and <code>npm test</code>. E2E checks contact deployed resources; mocks alone do not satisfy them. Also run the applicable build and coverage commands required by the submission instructions. Do not invent or rewrite template scripts to hide failures.</p><p>Never modify predefined test files or rely on changing tests for acceptance. The supplied homework calls its synced directory <code>src/test/</code>, while the repository guidelines also protect <code>src/tests</code>; preserve the template&#39;s actual layout and treat predefined tests in either location as read-only. Test synchronization belongs to the course workflow, not permission to edit test assertions.</p><p><strong>Only the user may push.</strong> Course references to pushing, remote submission and merging describe learner-owned submission steps, not actions for an assistant to execute. The template&#39;s required <code>task-N</code> branch names take precedence over a generic branch naming preference when implementing those assignments.</p><h2 id="evidence-for-every-required-module" tabindex="-1">Evidence for every required module <a class="header-anchor" href="#evidence-for-every-required-module" aria-label="Permalink to “Evidence for every required module”">​</a></h2><p>Record the source revision, runtime and lockfile; account/Region with sensitive values redacted; actual commands and outcomes; infrastructure and endpoint observations; a failure or denial where specified; cleanup and remaining charges/resources. Never include credentials, session tokens, passwords or full presigned URLs in public evidence.</p><p>Keep status separate from documentation: <code>not_started → in_progress → evidence_ready → reviewed</code>. A supplied PDF walkthrough or passing example is not independent completion. See the existing <a href="./../learning-projects.html#retain-a-real-evidence-record">evidence-record format</a>.</p><h2 id="corrections-and-safe-scope" tabindex="-1">Corrections and safe scope <a class="header-anchor" href="#corrections-and-safe-scope" aria-label="Permalink to “Corrections and safe scope”">​</a></h2><p>Read the <a href="./source-notes.html">source corrections</a> before live work. They distinguish original course requirements from technical errors, dated prices and lab-only configurations. Use an owned learning environment and synthetic data for public-access and deletion demonstrations. Cleanup must account for resources needed by later modules; recreate from infrastructure definitions when needed.</p><p>The <a href="./source-notes.html#source-register">source register</a> identifies the supplied documents. Original text attachments are retained as downloadable references; the Associate inline tasks are organized into actionable checklists. PDF guides remain supporting walkthroughs, with their substantive bonus exercises mapped into required pages.</p>',20)])])}const m=t(o,[["render",s]]);export{u as __pageData,m as default};
